<script setup>import {ref,computed} from 'vue';import {photos} from '../data.js';import Gallery from '../components/Gallery.vue';import PhotoViewer from '../components/PhotoViewer.vue';import {readArray} from '../storage.js';const ids=ref(readArray('casil-favorites'));const saved=computed(()=>photos.filter(p=>ids.value.includes(p.id)));const active=ref(null);function toggle(p){ids.value=ids.value.filter(x=>x!==p.id);localStorage.setItem('casil-favorites',JSON.stringify(ids.value))}function move(n){let i=saved.value.findIndex(p=>p.id===active.value.id);active.value=saved.value[(i+n+saved.value.length)%saved.value.length]}</script><template><section class="page-hero"><span class="eyebrow">Your collection</span><h1>Saved<br/>photographs.</h1><p>A browser-local collection of frames you want to revisit.</p></section><section class="section"><div class="notice">Favorites are saved in this browser only. They are not synchronized across devices.</div><Gallery v-if="saved.length" :photos="saved" :favorites="ids" @favorite="toggle" @open="active=$event"/><div v-else class="empty"><h2>No saved photos yet</h2><p>Tap the heart on any image to keep it here.</p><RouterLink class="button" to="/portfolio">Browse the portfolio</RouterLink></div><PhotoViewer :photo="active" @close="active=null" @move="move"/></section></template>
